"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[9864],{49864:a=>{a.exports=JSON.parse('{"meta":{"title":"Voluntariado - iMuslim Life","description":"Ayuda a musulmanes de todo el mundo a rezar a tiempo y leer el Cor\xe1n en su idioma. Hazte voluntario: traducci\xf3n, recitaci\xf3n, revisi\xf3n, escritura, pruebas o embajador de mezquita."},"chip":"Hazte voluntario","h1":"Tus habilidades pueden ser una sadaqa yariya","lede":"Salat-e-Mustaqeem e iMuslim Life son gratuitos, sin anuncios, y los usan cada d\xeda musulmanes de todo el mundo. Unas pocas horas de tu tiempo pueden ayudar a alguien a rezar a tiempo, entender el Cor\xe1n en su idioma o encontrar la mezquita m\xe1s cercana, una y otra vez.","heroCta":"Escr\xedbenos para ayudar","hadith":{"text":"\xabQuien gu\xeda hacia un bien tendr\xe1 una recompensa como la de quien lo realiza.\xbb","source":"El Profeta Muhammad (la paz sea con \xe9l), Sahih Muslim 1893"},"why":"Cada palabra que traduces la leen personas que nunca conocer\xe1s. Cada recitaci\xf3n que grabas se escucha en hogares, coches y mezquitas. Somos un equipo peque\xf1o, y son los voluntarios quienes llevan este trabajo a cada idioma y cada rinc\xf3n del mundo.","rolesH2":"C\xf3mo puedes ayudar","rolesSub":"Elige lo que mejor te encaje. No necesitas experiencia t\xe9cnica: solo sinceridad, cuidado y un poco de tiempo.","roleCta":"Puedo ayudar","roles":{"translate":{"title":"Traductores","text":"Lleva la app, la web, las s\xfaplicas y las historias semanales a tu idioma: \xe1rabe, urdu, franc\xe9s, espa\xf1ol, turco, indonesio, malayo, bengal\xed, hindi y m\xe1s. Revisamos cada traducci\xf3n antes de publicarla.","time":"Desde 1\u20132 horas a la semana"},"recite":{"title":"Recitadores","text":"Si Allah te ha bendecido con una voz hermosa y un tajwid correcto, graba recitaciones del Cor\xe1n, s\xfaplicas o el adhan para oyentes de todo el mundo. Te ayudamos con la grabaci\xf3n y la edici\xf3n.","time":"Graba a tu ritmo"},"review":{"title":"Eruditos y revisores","text":"Estudiantes de conocimiento, imames y maestros: revisad la exactitud y las fuentes de traducciones, historias y respuestas de los cuestionarios, para que todo lo que publicamos sea fiable.","time":"Revisa cuando puedas"},"write":{"title":"Escritores y narradores","text":"Ayuda a escribir las historias semanales de los Profetas, los Compa\xf1eros y la Sira para familias y ni\xf1os, en espa\xf1ol u otro idioma, siempre con fuentes aut\xe9nticas.","time":"Una historia al mes ya es una gran ayuda"},"test":{"title":"Probadores","text":"Prueba las novedades antes de su lanzamiento en iPhone, Android o Alexa, y cu\xe9ntanos qu\xe9 parece incorrecto o confuso. Una mirada nueva ve lo que se nos escapa.","time":"Unos minutos por versi\xf3n"},"masjid":{"title":"Embajadores de mezquita","text":"Ayuda a tu mezquita a publicar sus horarios de iqama y de Yumu\u2019a para que su comunidad los vea en la app, en la web y en Alexa. Gratis para todas las mezquitas.","time":"Una conversaci\xf3n puede servir a toda una comunidad"}},"stepsH2":"C\xf3mo funciona","steps":{"s1":{"title":"Escr\xedbenos","text":"Cu\xe9ntanos qu\xe9 papel, qu\xe9 idiomas dominas y un poco sobre ti."},"s2":{"title":"Te respondemos en persona","text":"Te contestamos con una gu\xeda breve y una primera tarea peque\xf1a."},"s3":{"title":"Tu trabajo se publica","text":"Tras la revisi\xf3n, tu aportaci\xf3n llega a personas de todo el mundo."}},"promiseH2":"Lo que puedes esperar de nosotros","promise":{"p1":{"title":"Tu tiempo, tu ritmo","text":"Sin compromiso m\xednimo. Ayuda cuando puedas y haz una pausa cuando lo necesites."},"p2":{"title":"Tu nombre, si quieres","text":"Nos alegrar\xe1 agradec\xe9rtelo por tu nombre, o mantener tu ayuda entre t\xfa y Allah. T\xfa decides."},"p3":{"title":"Cuidado por la exactitud","text":"El contenido religioso se revisa y se documenta antes de publicarse. Nunca cargas con eso solo."},"p4":{"title":"Respeto a tu privacidad","text":"Usamos tu correo solo para trabajar contigo; nunca lo compartimos ni te a\xf1adimos a listas de correo."}},"finalH2":"\xbfListo para ayudar?","finalText":"Env\xedanos un solo correo. Aunque no sepas d\xf3nde encajas, escr\xedbenos y encontraremos juntos el lugar adecuado, in sha Allah."}')}}]);